def dic(name, cls=''):
    """Inline outline icon. `cls` adds size or tone classes (d-ic-sm, d-ic-xs, d-flip)."""
    klass = 'd-ic' + (' ' + cls if cls else '')
    if name == 'wa':
        return f'<svg class="{klass} d-ic-wa" viewBox="0 0 24 24" aria-hidden="true"><path d="{WA_PATH}"/></svg>'
    return f'<svg class="{klass}" viewBox="0 0 24 24" aria-hidden="true"><path d="{D_PATHS[name]}"/></svg>'


def tile(name, tone='br', cls=''):
    """Tinted square icon tile. tone: br (brass), bl (blue), gr (green)."""
    klass = f'd-tile d-t-{tone}' + (' ' + cls if cls else '')
    return f'<span class="{klass}">{dic(name)}</span>'
